// The inline string idioms of VC6 /O2 (repne scasb / rep movsd / rep movsb): plain byte loops give the same memory.
static inline unsigned Len(const char* s) { unsigned n = 0; while (s[n] != 0) n++; return n; }
static inline void Cpy(char* d, const char* s) { unsigned k = 0; do { d[k] = s[k]; } while (s[k++] != 0); }
static inline void Cat(char* d, const char* s) { Cpy(d + Len(d), s); }

